function buildSeed() {
  const rooms = [];
  const tenants = [];
  let ti = 1;
  STUDIO_NOS.forEach((no, i) => {
    const id = "r" + no;
    const info = TENANT_INFO[no];
    const name = info && info.name ? info.name : "";
    const tid = name ? "t" + ti++ : null;
    const bld = STUDIO_BUILDINGS.find(b => b.prefix === studioPrefix(no));
    rooms.push({
      id, no, title: isStoreNo(no) ? "店面" : "套房",
      rent: studioRentOf(no), deposit: studioDepositOf(studioRentOf(no)),
      kind: isStoreNo(no) ? "store" : "studio",
      shop: (info && info.shop) || "",
      group: bld ? bld.no : "",
      street: bld ? bld.street : "",
      company: bld ? bld.company : "統潔",
      status: name ? "rented" : "vacant",
      tenantId: tid, photos: photosFor(no), amenities: AMENITIES,
      utilities: { electric: "5樓設有自助儲值機可以刷卡儲值", water: WATER_FEE_TEXT },
      contractImages: [], location: roomAddress(no)
    });
    if (!name) return;
    tenants.push({
      id: tid, name,
      phone: info.phone || "",
      idNo: "",
      address: "",
      emergencyName: "",
      emergencyPhone: "",
      roomId: id,
      leaseStart: info.leaseStart || "",
      leaseEnd: info.leaseEnd || "",
      dueDay: 1,
      paid: true,
      note: "",
      bankLast5: info.bankLast5 || ""
    });
  });
  rooms.push({
    id: "r7651", no: "7651", title: "辦公室", rent: 5000, deposit: 0, status: "office", kind: "studio",
    tenantId: "t7651", photos: photosFor("7651"), amenities: ["冷氣", "網路", "書桌椅"],
    utilities: { electric: "公司自付", water: "公司自付" }, contractImages: [], location: roomAddress("7651")
  });
  tenants.push({
    id: "t7651",
    name: "吳慧青",
    phone: "",
    idNo: "",
    address: "",
    emergencyName: "",
    emergencyPhone: "",
    roomId: "r7651",
    leaseStart: "",
    leaseEnd: "",
    dueDay: 1,
    paid: true,
    paidAt: "2026-07-03 10:00",
    subsidy: true,
    note: TENANT_INFO["7651"].note
  });
  factoryRooms().forEach(r => {
    const info = FACTORY_TENANT_INFO[r.no];
    if (info && info.name) {
      const tid = "tf-" + r.no;
      r.tenantId = tid;
      r.status = "rented";
      r.rent = info.rent || 0;
      r.rentUntaxed = info.rentUntaxed || 0;
      tenants.push({
        id: tid, name: info.name, phone: info.phone || "", taxId: info.taxId || "",
        contactName: info.contactName || "", idNo: info.idNo || "", address: info.invoiceAddr || "",
        emergencyName: "", emergencyPhone: "", roomId: r.id,
        leaseStart: info.leaseStart || "", leaseEnd: info.leaseEnd || "",
        dueDay: info.dueDay || 1, paid: false, note: info.note || "", rentUntaxed: info.rentUntaxed || 0,
        payBank: info.payBank || "", payCompany: info.payCompany || "", deposit: info.deposit || 0
      });
    }
    rooms.push(r);
  });
  return {
    rooms, tenants,
    repairs: [],
    notices: [],
    announcements: [],
    houseRules: DEFAULT_RULES,
    renewals: []
  };
}
