      at: r.appointAt, kind: "repair", id: r.id, item: r,
      title: `${room ? room.no : ""} ${r.type}維修`,
      sub: `${tenant ? tenant.name : ""} · ${formatDateTime12(String(r.appointAt).replace("T", " "))}`
