  const joint = accountStats("聯名戶", b.start, b.end);
  const totalBal = stats.reduce((s, x) => s + x.bal, 0) + joint.bal;
  const totalIn = stats.reduce((s, x) => s + x.inn, 0) + joint.inn;
  const totalOut = stats.reduce((s, x) => s + x.out, 0) + joint.out;
