function guessPassbookType(line, nums) {
  const s = String(line || "");
  const outHit = /支出|提款|轉出|扣款|匯出|手續費|退押|退還押金|繳費|繳款|現提|金融卡提款|轉帳支出|跨行手續|本行轉出|還本|壽險|火震|保險|EAH/.test(s);
  const inHit = /存入|匯入|轉入|利息|放款|入帳|現存|轉帳存入|薪轉|租金|現金存款|金融卡轉入|IC轉|ＩＣ轉|I\s*C轉|活息|CER/.test(s);
  if (outHit && !inHit) return "out";
  if (inHit && !outHit) return "in";
  const n = (nums || []).filter(v => Number(v) >= 100);
  if (n.length >= 3) {
    const bal = Math.max.apply(null, n);
    const left = n[0], mid = n[1];
    const lastIsBal = n[n.length - 1] === bal;
    if (lastIsBal) {
      if (left >= 100 && left !== bal && !(mid >= 100 && mid !== bal)) return "out";
      if (mid >= 100 && mid !== bal && !(left >= 100 && left !== bal)) return "in";
    }
  }
  return "";
}
function looksLikeNonghui(text) {
  const s = String(text || "");
  if (/支出金額/.test(s) && /存入金額/.test(s)) return true;
  if (/結存金額/.test(s) && /摘要/.test(s)) return true;
  if (/竭誠為您服務/.test(s)) return true;
  const n = (s.replace(/\s+/g, "").match(/11[0-9]\d{4}/g) || []).length;
  return n >= 2;
}
function nonghuiMoneyList(chunk) {
  let s = String(chunk || "").replace(/\([^)]*\)/g, " ");
  const out = [];
  const push = raw => {
    const v = parseNonghuiMoneyToken(raw);
    if (v >= 1 && v < 2000000) out.push(v);
  };
  s.replace(/[＊*%$xX]\s*([\d,]+(?:[.,]\d{2})?)/g, (_, n) => push(n));
  if (out.length) return out;
  s.replace(/(\d{1,3}(?:,\d{3})+[.,]\d{2}|\d+[.,]\d{2})/g, (_, n) => push(n));
  return out;
}
function nonghuiCompact(text) {
  return String(text || "")
    .replace(/\u3000/g, " ")
    .replace(/[ＩIl1]\s*[ＣCｃ]\s*轉/g, "IC轉")
    .replace(/[ＩI]C轉/g, "IC轉")
    .replace(/帳號[:：]?\s*[\d-]+/g, "|")
    .replace(/本數[:：]?\d{1,3}(?=11[0-9]|12[0-5]|\||$)/g, "|")
    .replace(/本數[:：]?\d+/g, "|")
    .replace(/\([^)]{0,48}\)/g, "|")
    .replace(/B\d{4}(?=11[0-9]|12[0-5]|\||$)/gi, "|")
    .replace(/B\d{4}/gi, "|")
    .replace(/備註|結存金額|支出金額|存入金額|年月日|摘要|竭誠為您服務/g, "|")
    .replace(/\.00/g, ".00|")
    .replace(/\s+/g, "");
}
function nonghuiDateHits(s) {
  const hits = [];
  const re7 = /(11[0-9]|12[0-5])(0[1-9]|1[0-2])(0[1-9]|[12]\d|3[01])/g;
  let m;
  while ((m = re7.exec(s))) {
    const y = Number(m[1]), mo = Number(m[2]), d = Number(m[3]);
    if (y < 110 || y > 120 || mo < 1 || mo > 12 || d < 1 || d > 31) continue;
    if (hits.length && m.index < hits[hits.length - 1].i + hits[hits.length - 1].len) continue;
    hits.push({
      i: m.index,
      len: 7,
      date: (y + 1911) + "-" + String(mo).padStart(2, "0") + "-" + String(d).padStart(2, "0")
    });
  }
  const reS = /(11[0-9]|12[0-5])[\/.\-年](\d{1,2})[\/.\-月]?(\d{1,2})/g;
  while ((m = reS.exec(s))) {
    const y = Number(m[1]), mo = Number(m[2]), d = Number(m[3]);
    if (y < 110 || y > 120 || mo < 1 || mo > 12 || d < 1 || d > 31) continue;
    if (hits.some(h => Math.abs(h.i - m.index) < 3)) continue;
    hits.push({
      i: m.index,
      len: m[0].length,
      date: (y + 1911) + "-" + String(mo).padStart(2, "0") + "-" + String(d).padStart(2, "0")
    });
  }
  hits.sort((a, b) => a.i - b.i);
  return hits;
}
function nonghuiLessonHits(s) {
  const rules = [
    { re: /火震險?\d*/g, note: "火震險", type: "out" },
    { re: /人壽險|人壽|壽險/g, note: "人壽險", type: "out" },
    { re: /還本息\d*|還本|本息|EAH\d*/gi, note: "還本息", type: "out" },
    { re: /活息/g, note: "活息", type: "in" },
    { re: /IC轉\d{0,4}|I\s*C轉\d{0,4}|CER\s*700|轉700|轉812/gi, note: "IC轉", type: "in" }
  ];
  const hits = [];
  rules.forEach(rule => {
    const re = new RegExp(rule.re.source, rule.re.flags.includes("g") ? rule.re.flags : rule.re.flags + "g");
    let m;
    while ((m = re.exec(s))) hits.push({ i: m.index, len: m[0].length, note: rule.note, type: rule.type });
  });
  hits.sort((a, b) => a.i - b.i || b.len - a.len);
  const kept = [];
  hits.forEach(h => {
    if (kept.some(k => h.i < k.i + k.len && k.i < h.i + h.len)) return;
    kept.push(h);
  });
  return kept.sort((a, b) => a.i - b.i);
}
function parseNonghuiPassbook(text, defaults) {
  const defCo = (defaults && defaults.company) || "統潔";
  const compact = nonghuiCompact(text);
  const dates = nonghuiDateHits(compact);
  const rows = [];
  const pushRow = (date, lesson, window) => {
    if (!date || !lesson) return;
    if (/帳號|本數/.test(window)) return;
    const money = nonghuiMoneyList(window);
    if (!money.length) return;
    const amount = money[0];
    if (lesson.note !== "活息" && amount < 100) return;
    if (!(amount >= 1 && amount < 2000000)) return;
    rows.push({
      date,
      type: lesson.type,
      amount,
      company: defCo,
      bank: "農會",
      note: lesson.note
    });
  };
  dates.forEach((d, idx) => {
    const end = idx + 1 < dates.length ? dates[idx + 1].i : compact.length;
    const window = compact.slice(d.i + d.len, end);
    const lessons = nonghuiLessonHits(window);
    if (!lessons.length) return;
    if (lessons.length === 1) {
      pushRow(d.date, lessons[0], window);
      return;
    }
    lessons.forEach((lesson, li) => {
      const wEnd = li + 1 < lessons.length ? lessons[li + 1].i : window.length;
      pushRow(d.date, lesson, window.slice(lesson.i, wEnd));
    });
  });
  return rows;
}
function parseStarMoney(line) {
  const out = [];
  const push = n => {
    const v = Number(String(n).replace(/,/g, ""));
    if (v > 0 && v < 100000000) out.push(v);
  };
  String(line || "").replace(/[＊*★☆xX]\s*([\d,]+(?:\.\d+)?)/g, (_, n) => push(n));
  if (out.length) return out;
  String(line || "").replace(/(\d{1,3}(?:,\d{3})+(?:\.\d{2})|\d+\.\d{2})/g, (_, n) => push(n));
  return out;
}
function rocYmd7(line) {
  const s = String(line || "").replace(/\s+/g, "");
  const m = s.match(/(1[0-2]\d)(\d{2})(\d{2})/);
  if (!m) return "";
  let y = Number(m[1]), mo = Number(m[2]), d = Number(m[3]);
  if (y < 90 || y > 199 || mo < 1 || mo > 12 || d < 1 || d > 31) return "";
  y += 1911;
  return y + "-" + String(mo).padStart(2, "0") + "-" + String(d).padStart(2, "0");
}
function nonghuiNote(line) {
  let s = String(line || "");
  s = s.replace(/帳號[:：]?\s*[\d-]+/g, "");
  s = s.replace(/\*\s*[\d,]+(?:\.\d+)?/g, " ");
  s = s.replace(/\(\s*[^)]{0,24}\)/g, " ");
  s = s.replace(/\b\d{9,}\b/g, " ");
  s = s.replace(/1[0-2]\d\d{4}/, " ");
  s = s.replace(/\bB\d{3,5}\b/g, " ");
  s = s.replace(/\b\d{1,2}\/\d{1,2}\b/g, " ");
  s = s.replace(/本數[:：]?\s*\d+/g, " ");
  s = s.replace(/結存|支出金額|存入金額|備註/g, " ");
  return s.replace(/\s+/g, " ").trim().slice(0, 48);
}
function parseNonghuiMoneyToken(raw) {
  let s = String(raw || "").replace(/[^\d.,]/g, "");
  if (!s) return 0;
  let m = s.match(/^(\d{1,3}(?:,\d{3})+)[.,](\d{2})/);
  if (m) return Number(m[1].replace(/,/g, ""));
  m = s.match(/^(\d+)[.,](\d{2})/);
  if (m) return Number(m[1]);
  m = s.match(/^(\d{1,3}(?:,\d{3})+)$/);
  if (m) return Number(m[1].replace(/,/g, ""));
  const n = Number(s.replace(/,/g, ""));
  return n > 0 && n < 2000000 ? n : 0;
}
function parsePassbookOcr(text, defaults) {
  const defCo = (defaults && defaults.company) || "統潔";
  const defBank = (defaults && defaults.bank) || "";
  const auto = defaults && defaults.type === "auto";
  const defType = auto ? "" : (defaults && defaults.type === "out" ? "out" : "in");
  const nh = parseNonghuiPassbook(text, defaults);
  if (nh.length) return nh;
  if (looksLikeNonghui(text)) return [];
  const rows = [];
  String(text || "").replace(/\u3000/g, " ").split(/\n+/).forEach(raw => {
    const line = String(raw || "").trim();
    if (!line) return;
    if (/帳號/.test(line)) return;
    const dm = line.match(/(1[0-2]\d{2}|20\d{2}|\d{2,3})[\/.\-年]?\s*(\d{1,2})[\/.\-月]?\s*(\d{1,2})/);
    const compact7 = rocYmd7(line);
    const compact = line.replace(/\s+/g, "").match(/(1[0-2]\d{2})(\d{2})(\d{2})/);
    let y = 0, m = 0, d = 0, date = compact7;
    if (!date && dm) { y = Number(String(dm[1]).replace(/\D/g, "")); m = Number(dm[2]); d = Number(dm[3]); }
    else if (!date && compact) { y = Number(compact[1]); m = Number(compact[2]); d = Number(compact[3]); }
    if (!date) {
      if (!y) return;
      if (y < 200) y += 1911;
      if (m < 1 || m > 12 || d < 1 || d > 31) return;
      date = y + "-" + String(m).padStart(2, "0") + "-" + String(d).padStart(2, "0");
    }
    const star = parseStarMoney(line);
    const nums = star.length ? star.slice() : [];
    if (!nums.length) {
      line.replace(/,/g, "").replace(/(\d{3,})/g, (_, n) => {
        const v = Number(n);
        if (v >= 100 && v < 100000000) nums.push(v);
      });
    }
    if (!nums.length) return;
    let amount = nums.length >= 2 ? nums[nums.length - 2] : nums[0];
    const guessed = guessPassbookType(line, nums);
    const type = guessed || defType;
    if (type !== "in" && type !== "out") return;
    rows.push({
      date, type, amount, company: defCo,
      bank: defBank,
      note: (nonghuiNote(line) || line).slice(0, 48)
    });
  });
  return rows;
}
function loadTesseract() {
  if (window.Tesseract) return Promise.resolve(window.Tesseract);
  return new Promise((resolve, reject) => {
    const s = document.createElement("script");
    s.src = "https://cdn.jsdelivr.net/npm/tesseract.js@5/dist/tesseract.min.js";
    s.onload = () => window.Tesseract ? resolve(window.Tesseract) : reject(new Error("tesseract"));
    s.onerror = () => reject(new Error("tesseract"));
    document.head.appendChild(s);
  });
}
async function prepPassbookImage(file) {
  try {
    const bmp = await createImageBitmap(file, { imageOrientation: "from-image" });
    const w0 = bmp.width, h0 = bmp.height;
    const scale = Math.max(1.4, Math.min(2.2, 1600 / Math.max(w0, 1)));
    const w = Math.round(w0 * scale), h = Math.round(h0 * scale);
    const canvas = document.createElement("canvas");
    canvas.width = w; canvas.height = h;
    const ctx = canvas.getContext("2d", { willReadFrequently: true });
    ctx.drawImage(bmp, 0, 0, w, h);
    const img = ctx.getImageData(0, 0, w, h);
    const d = img.data;
    for (let i = 0; i < d.length; i += 4) {
      let g = d[i] * 0.3 + d[i + 1] * 0.59 + d[i + 2] * 0.11;
      g = (g - 128) * 1.55 + 136;
      g = g < 95 ? 0 : (g > 210 ? 255 : g);
      d[i] = d[i + 1] = d[i + 2] = g;
    }
    ctx.putImageData(img, 0, 0);
    try { bmp.close(); } catch {}
    return canvas;
  } catch {
    return file;
  }
}
async function makeOcrWorker() {
  const T = await loadTesseract();
  if (!T || !T.createWorker) return null;
  const langs = ["chi_tra+eng", "chi_tra", "eng"];
  for (let i = 0; i < langs.length; i++) {
    try {
      const w = await T.createWorker(langs[i]);
      if (w) return w;
    } catch {}
  }
  return null;
}
async function ocrPassbookFile(file, worker) {
  const img = await prepPassbookImage(file);
  const texts = [];
  if (worker) {
    for (let p = 0; p < 2; p++) {
      try {
        if (worker.setParameters) await worker.setParameters({ tessedit_pageseg_mode: String(p === 0 ? 6 : 4) });
        const ret = await worker.recognize(img);
        const t = ret && ret.data && ret.data.text ? String(ret.data.text) : "";
        if (t.trim()) texts.push(t);
      } catch {}
    }
  }
  return texts.join("\n");
}
async function fileToVisionJpeg(file) {
  try {
    const bmp = await createImageBitmap(file, { imageOrientation: "from-image" });
    const max = 1600;
    const scale = Math.min(1, max / Math.max(bmp.width, bmp.height, 1));
    const w = Math.max(1, Math.round(bmp.width * scale));
    const h = Math.max(1, Math.round(bmp.height * scale));
    const canvas = document.createElement("canvas");
    canvas.width = w; canvas.height = h;
    canvas.getContext("2d").drawImage(bmp, 0, 0, w, h);
    try { bmp.close(); } catch {}
    const blob = await new Promise(r => canvas.toBlob(r, "image/jpeg", 0.88));
    if (!blob) return "";
    const buf = await blob.arrayBuffer();
    const bytes = new Uint8Array(buf);
    let bin = "";
    const chunk = 0x8000;
    for (let i = 0; i < bytes.length; i += chunk) {
      bin += String.fromCharCode.apply(null, bytes.subarray(i, i + chunk));
    }
    return btoa(bin);
  } catch {
    return "";
  }
}
async function ocrPassbookCloud(file) {
  const key = String((state && state.visionKey) || "").trim();
  if (!key) return "";
  const image = await fileToVisionJpeg(file);
  if (!image) { ui.visionLastError = "照片轉檔失敗"; return ""; }
  try {
    const res = await fetch("https://vision.googleapis.com/v1/images:annotate?key=" + encodeURIComponent(key), {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        requests: [{
          image: { content: image },
          features: [{ type: "DOCUMENT_TEXT_DETECTION" }],
          imageContext: { languageHints: ["zh-Hant", "zh-TW", "en"] }
        }]
      })
    });
    const data = await res.json();
    const err = (data && data.error) || (data && data.responses && data.responses[0] && data.responses[0].error);
    if (err) {
      ui.visionLastError = visionErrText(err);
      return "";
    }
    const resp = data && data.responses && data.responses[0];
    const text = (resp && resp.fullTextAnnotation && resp.fullTextAnnotation.text)
      || (resp && resp.textAnnotations && resp.textAnnotations[0] && resp.textAnnotations[0].description)
      || "";
    if (String(text).trim()) {
      bumpVisionCount();
      ui.visionLastError = "";
      return String(text);
    }
    ui.visionLastError = "雲端沒讀到字";
    return "";
  } catch {
    ui.visionLastError = "連不上 Google";
    return "";
  }
}
function visionErrText(err) {
  const msg = String((err && (err.message || err.status || err.statusText)) || err || "");
  if (/API_KEY_SERVICE_BLOCKED|SERVICE_BLOCKED/i.test(msg)) {
    return "金鑰還沒開放 Gemini。請啟用 Gemini API，並在金鑰的 API 限制勾選 Generative Language API";
  }
  if (/API key not valid|API_KEY_INVALID/i.test(msg)) return "金鑰無效，請重新貼上";
  if (/PERMISSION_DENIED|has not been used|disabled|not enabled|FAILED_PRECONDITION/i.test(msg) && /generativelanguage|Gemini/i.test(msg)) {
    return "尚未啟用 Gemini API，請到程式庫搜尋 Gemini 並啟用";
  }
  if (/PERMISSION_DENIED|has not been used|disabled|not enabled/i.test(msg)) return "尚未啟用對應的 Google API";
  if (/billing|BILLING/i.test(msg)) return "Google 要先開帳單，額度內不會扣錢";
  return msg.slice(0, 120) || "雲端看圖失敗";
}
const GEMINI_MODELS = ["gemini-2.0-flash", "gemini-2.5-flash", "gemini-2.0-flash-lite", "gemini-flash-latest"];
function geminiPassbookPrompt() {
  return "這是台灣農會存摺照片。請讀每一筆「左邊有日期」的交易，輸出 JSON 陣列。\n"
    + "規則：\n"
    + "1. 日期是民國7碼，如 1131213＝113年12月13日＝西元2024-12-13（民國年+1911）\n"
    + "2. 摘要欄才是備註：IC轉、還本息、活息、人壽險、火震險。不要讀最右邊備註欄（B1216、06/03 那些）\n"
    + "3. * 只表示金額在支出欄或存入欄，不要記入\n"
    + "4. 支出金額右邊括號()內容不要\n"
    + "5. 結存金額不要入帳\n"
    + "6. 沒有日期的行不要（帳號、本數、標題、空行）\n"
    + "7. IC轉、活息＝進帳 in；還本息、人壽險、火震險＝出帳 out\n"
    + "8. amount 是該行支出或存入的整數，不要小數、不要逗號、不要結存\n"
    + "只輸出 JSON，不要其他字：\n"
    + "[{\"date\":\"2024-12-13\",\"type\":\"in\",\"amount\":23000,\"note\":\"IC轉\"}]";
}
function parseGeminiBookRows(raw, defaults) {
  let s = String(raw || "").trim();
  s = s.replace(/^```(?:json)?\s*/i, "").replace(/```$/i, "").trim();
  const m = s.match(/\[[\s\S]*\]/);
  if (!m) return [];
  let arr;
  try { arr = JSON.parse(m[0]); } catch { return []; }
  if (!Array.isArray(arr)) return [];
  const defCo = (defaults && defaults.company) || "統潔";
  const defBank = (defaults && defaults.bank) || "農會";
  const out = [];
  arr.forEach(item => {
    if (!item) return;
    let date = String(item.date || "").trim();
    const roc7 = date.replace(/\D/g, "");
    if (/^\d{7}$/.test(roc7)) {
      const y = Number(roc7.slice(0, 3)) + 1911;
      date = y + "-" + roc7.slice(3, 5) + "-" + roc7.slice(5, 7);
    } else {
      const p = date.match(/^(\d{2,3})[\/.\-](\d{1,2})[\/.\-](\d{1,2})$/);
      if (p) {
        let y = Number(p[1]);
        if (y < 200) y += 1911;
        date = y + "-" + String(Number(p[2])).padStart(2, "0") + "-" + String(Number(p[3])).padStart(2, "0");
      }
    }
    if (!/^\d{4}-\d{2}-\d{2}$/.test(date)) return;
    let type = String(item.type || "").toLowerCase();
    const note0 = String(item.note || item.摘要 || "");
    if (type !== "in" && type !== "out") {
      if (/還本|壽險|火震|保險|支出/.test(note0)) type = "out";
      else if (/IC轉|ＩＣ轉|活息|存入/.test(note0)) type = "in";
    }
    if (type !== "in" && type !== "out") return;
    const amount = Math.round(Number(String(item.amount).replace(/[^\d.-]/g, "")) || 0);
    if (amount < 1 || amount >= 2000000) return;
    let note = note0;
    if (/火震/.test(note0)) note = "火震險";
    else if (/人壽|壽險/.test(note0)) note = "人壽險";
    else if (/還本|本息/.test(note0)) note = "還本息";
    else if (/活息/.test(note0)) note = "活息";
    else if (/IC|ＩＣ|轉700|轉812/.test(note0)) note = "IC轉";
    else note = String(note0).replace(/\d{4,}/g, "").trim().slice(0, 24) || (type === "in" ? "存入" : "支出");
    out.push({ date, type, amount, company: defCo, bank: defBank, note });
  });
  return out;
}
async function readPassbookGemini(file, defaults) {
  const key = String((state && state.visionKey) || "").trim();
  if (!key) return [];
  const image = await fileToVisionJpeg(file);
  if (!image) { ui.visionLastError = "照片轉檔失敗"; return []; }
  const models = ui.geminiModel ? [ui.geminiModel].concat(GEMINI_MODELS.filter(m => m !== ui.geminiModel)) : GEMINI_MODELS.slice();
  let lastErr = "";
  for (let i = 0; i < models.length; i++) {
    const model = models[i];
    try {
      const res = await fetch("https://generativelanguage.googleapis.com/v1beta/models/" + encodeURIComponent(model) + ":generateContent?key=" + encodeURIComponent(key), {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          contents: [{
            parts: [
              { inline_data: { mime_type: "image/jpeg", data: image } },
              { text: geminiPassbookPrompt() }
            ]
          }],
          generationConfig: { temperature: 0, responseMimeType: "application/json" }
        })
      });
      const data = await res.json();
      if (data && data.error) {
        lastErr = visionErrText(data.error);
        if (/金鑰無效|尚未啟用|還沒開放|帳單/.test(lastErr)) {
          ui.visionLastError = lastErr;
          return [];
        }
        continue;
      }
      const text = ((((data.candidates || [])[0] || {}).content || {}).parts || []).map(p => p && p.text).filter(Boolean).join("\n");
      const rows = parseGeminiBookRows(text, defaults);
      if (rows.length) {
        ui.geminiModel = model;
        ui.visionLastError = "";
        return rows;
      }
      lastErr = "Gemini 沒讀出完整帳";
    } catch {
      lastErr = "連不上 Gemini";
    }
  }
  ui.visionLastError = lastErr;
  return [];
}
