function forceVacateTenant(t) {
  if (!t) { toast("找不到租客"); return; }
  if (t.demo || isDemoTenant(t)) { toast("測試房請用重製"); return; }
  const roomNow = (state.rooms || []).find(x => x && x.id === t.roomId)
    || (state.rooms || []).find(x => x && String(x.no) === String(t.roomNo || ""));
  const no = roomNow && String(roomNow.no || "");
  if (studioMirrorHostNo(no) || studioMirrorGuestNos(no).length) {
    toast("7251 呂佳芸與 7651 吳慧青補助掛名綁在一起，不能單獨退租");
    return;
  }
  if (t.incoming || t.prospect) {
    cancelIncomingTenant(t);
    return;
  }
  const r = (state.rooms || []).find(x => x && x.id === t.roomId)
    || (state.rooms || []).find(x => x && String(x.no) === String(t.roomNo || ""));
  const roomId = (r && r.id) || t.roomId;
  const now = Date.now();
  (state.tenants || []).forEach(x => {
    if (!x || x.demo || x.id !== t.id) return;
    x.former = true;
    x.incoming = false;
    x.prospect = false;
    x.applyPending = false;
    x.applyUnread = false;
    x.leftOn = ymdOf(nowStamp());
    x.sessionEnded = true;
    x.clearedApply = true;
    x.loginRevoked = true;
    x.edited = true;
    x.editedAt = now;
    x.eSignRev = now;
    x.eSign = { status: "unsigned", cleared: true, ts: now, at: nowStamp() };
    x.signAppointAt = "";
    clearTenantAvatar(x);
    if (isPracticeStudioNo(no)) x.practiceStay = false;
  });
  try {
    if (!state.eSigns || typeof state.eSigns !== "object") state.eSigns = {};
    const gone = { status: "unsigned", cleared: true, ts: now, at: nowStamp() };
    state.eSigns[t.id] = gone;
    eSignAliasKeys(t, r).forEach(k => { state.eSigns[k] = gone; });
    persistESignsMap(Object.assign({}, loadLocalESigns(), state.eSigns));
  } catch {}
  restoreLiveRoom(r);
  if (Array.isArray(state.notices) && r) {
    state.notices = state.notices.filter(n => !(n && n.type === "apply" && n.roomNo === r.no));
  }
  pruneDeadApplyNotices(state);
  if (isPracticeStudioNo(no)) {
    try { purgePracticeRoomLedger(state, no); } catch {}
  }
  save();
  try { pushCloud(); } catch {}
  try { pushPhoneNotify("租約已結束", ((r && r.no) || "") + " 已辦理退租", (r && r.no) || "tenants"); } catch {}
  toast("已強制退租，" + ((r && r.no) || "") + (r && r.tenantId ? " 已交下一位" : " 改為空房"));
}
function completeHandover(oldT, r, co) {
  if (!r) return;
  if (oldT && !oldT.former) {
    oldT.former = true;
    oldT.incoming = false;
    oldT.leftOn = (co && co.at) || ymdOf(nowStamp());
    oldT.edited = true;
    oldT.sessionEnded = true;
    clearTenantAvatar(oldT);
  }
  const neu = incomingOf(r.id);
  if (r.no) unbindRoomLine(r.no, oldT);
  r.lineCleared = true;
  r.lineExpectName = neu ? (neu.name || "") : "";
  if (neu) {
    neu.incoming = false;
    neu.former = false;
    neu.prospect = false;
    neu.applyPending = false;
    neu.edited = true;
    neu.editedAt = Date.now();
    neu.dueDay = RENT_DUE_DAY;
    if (!neu.loginPass) neu.loginPass = phonePassOf(neu.phone);
    r.tenantId = neu.id;
    r.status = "rented";
    if (Number(neu.rent) > 0) r.rent = Number(neu.rent);
    if (Number(neu.deposit) > 0) r.deposit = Number(neu.deposit);
    else if (Number(neu.rent) > 0) r.deposit = Number(neu.rent) * 2;
    delete r.incomingTenantId;
    if (ui.role === "tenant" && ui.tenantId === neu.id) {
      ui.prospectPreview = false;
      persistUi();
    }
    try { pushPhoneNotify("入住已確認", `${r.no || ""} ${neu.name || ""} 已成為正式租客`, r.no || "tenants"); } catch {}
  } else {
    r.tenantId = null;
    if (r.status !== "repair") r.status = "vacant";
  }
  r.edited = true;
  pruneDeadApplyNotices(state);
}
function postCheckoutBooks(co, t, r) {
  if (!co || !t) return;
  if (isDemoTenant(t) || (r && isDemoRoom(r))) return;
  const refund = Number(co.refund) || 0;
  if (refund <= 0) return;
  if (!state.books) state.books = [];
  const id = "bk-co-" + co.id + "-refund";
  if (state.books.some(b => b && (b.id === id || b.importTag === "co-" + co.id))) return;
  const prorate = Number(co.prorate) || 0;
  const bits = ["退押金 " + money(Number(co.deposit) || 0)];
  if (Number(co.deduct)) bits.push("扣 " + money(co.deduct));
  if (prorate) bits.push("日租金 " + money(prorate));
  state.books.push({
    id,
    type: "out",
    date: co.at || ymdOf(nowStamp()),
    amount: refund,
    company: co.payAccount || "現金(保險箱)",
    bank: co.payBank || "",
    note: (co.kind === "early" ? "中途退租　" : "退租　") + (r && r.no || "") + " " + (t.name || "") + "　" + bits.join("＋"),
    roomNo: (r && r.no) || "",
    importTag: "co-" + co.id,
    createdAt: nowStamp()
  });
}
