function markTenantLineReported() {
  const t = me();
  if (!t) return;
  if (isDemoTenant(t)) {
    t.lineNotified = true;
    t.lineProofYm = payYmNow();
    t.edited = true;
    save();
    clearTimeout(saveTimer);
    try { pushCloud(); } catch {}
  }
}
function markTenantPaid(via) {
  const t = me(); const r = myRoom();
  if (!t || !r) return;
  t.paid = true;
  t.paidVia = via;
  t.paidAt = nowStamp();
  t.paidTouched = true;
  t.paidYm = payYmNow();
  if (!t.remitOn) t.remitOn = ymdOf(t.paidAt);
  if (via === "line") {
    t.lineNotified = true;
    t.lineProofYm = payYmNow();
  }
  stampPaidMark(state, t);
  try { ensureDemoTenant(state); } catch {}
  upsertRentAutoBookOn(state, t);
  mirrorPaidFromTenant(state, t);
  save();
  clearTimeout(saveTimer);
  try { pushCloud(); } catch {}
  pushPhoneNotify("繳費回報", `${r.no} ${t.name || ""} 已回報繳費（${via === "line" ? "官方 LINE" : "App"}）`, "admin");
}
function linePayMessage() {
  const t = me(); const r = myRoom();
  const pack = tenantPayAccounts(t, r);
  const b = pack.primary || {};
  return `【繳費通知】${r ? r.no : ""} ${t && t.name ? t.name : ""} 已繳本月租金 ${r ? money(thisMonthRentOf(t, r)) : ""}\n戶名：${b.holder || "統潔開發有限公司"}\n銀行：${[b.code, b.bank].filter(Boolean).join(" ")}\n帳號：${b.account || ""}`;
}
