function bindAiBlockReorder() {
  const box = document.getElementById("ai-blocks");
  if (!box) return;
  let dragEl = null, startY = 0, holdX = 0, originY = 0, armed = false, moved = false;
  const items = () => [...box.querySelectorAll(":scope > .ai-block")];
  const pt = e => {
    if (e.touches && e.touches[0]) return { x: e.touches[0].clientX, y: e.touches[0].clientY };
    if (e.changedTouches && e.changedTouches[0]) return { x: e.changedTouches[0].clientX, y: e.changedTouches[0].clientY };
    return { x: e.clientX, y: e.clientY };
  };
  const follow = y => {
    if (!dragEl) return;
    dragEl.style.transform = "translate3d(0," + (y - startY) + "px,0)";
  };
  const onMove = e => {
    if (!dragEl) return;
    const p = pt(e);
    if (!armed) {
      const dy = p.y - originY, dx = p.x - holdX;
      if (Math.abs(dx) > 16 && Math.abs(dx) > Math.abs(dy)) { dragEl = null; return; }
      if (Math.abs(dy) < 10) return;
      armed = true;
      moved = true;
      box.classList.add("sorting");
      dragEl.classList.add("dragging");
      try { if (navigator.vibrate) navigator.vibrate(10); } catch {}
    }
    if (e.cancelable) e.preventDefault();
    moved = true;
    follow(p.y);
    const midY = dragEl.getBoundingClientRect().top + dragEl.offsetHeight / 2;
    for (const t of items()) {
      if (t === dragEl) continue;
      const mid = t.getBoundingClientRect().top + t.offsetHeight / 2;
      const from = items().indexOf(dragEl);
      const to = items().indexOf(t);
      if (from < to && midY > mid) {
        const top = dragEl.getBoundingClientRect().top;
        box.insertBefore(dragEl, t.nextSibling);
        startY += dragEl.getBoundingClientRect().top - top;
        follow(p.y);
        break;
      }
      if (from > to && midY < mid) {
        const top = dragEl.getBoundingClientRect().top;
        box.insertBefore(dragEl, t);
        startY += dragEl.getBoundingClientRect().top - top;
        follow(p.y);
        break;
      }
    }
  };
  const onEnd = () => {
    window.removeEventListener("pointermove", onMove);
    window.removeEventListener("touchmove", onMove);
    window.removeEventListener("pointerup", onEnd);
    window.removeEventListener("touchend", onEnd);
    window.removeEventListener("pointercancel", onEnd);
    if (dragEl) {
      dragEl.style.transform = "";
      dragEl.classList.remove("dragging");
      if (moved) {
        dragEl.dataset.dragged = "1";
        saveAiBlockOrder(items().map(n => n.dataset.aiBlock));
      }
    }
    box.classList.remove("sorting");
    dragEl = null;
    armed = false;
    moved = false;
  };
  box.addEventListener("pointerdown", e => {
    const handle = e.target.closest(".ai-drag");
    if (!handle) return;
    e.preventDefault();
    e.stopPropagation();
    const block = handle.closest(".ai-block");
    if (!block) return;
    const p = pt(e);
    dragEl = block;
    startY = p.y;
    originY = p.y;
    holdX = p.x;
    armed = true;
    moved = false;
    box.classList.add("sorting");
    dragEl.classList.add("dragging");
    try { if (navigator.vibrate) navigator.vibrate(10); } catch {}
    window.addEventListener("pointermove", onMove, { passive: false });
    window.addEventListener("touchmove", onMove, { passive: false });
    window.addEventListener("pointerup", onEnd);
    window.addEventListener("touchend", onEnd);
    window.addEventListener("pointercancel", onEnd);
  }, true);
  box.addEventListener("click", e => {
    if (e.target.closest(".ai-drag")) { e.preventDefault(); e.stopPropagation(); }
  }, true);
}
function submitErrandNow() {
  if (!errandGuessList().length && String(ui.errandNote || "").trim()) {
    ui.errandGuesses = [inferOneFile({ name: ui.errandNote.trim() })];
  }
  const list = errandGuessList();
  if (!list.length) {
    if (ui.errandAbsorb) {
      toast("Excel 已記入進出帳");
      ui.errandAbsorb = "";
      ui.keepScroll = true;
      render();
      return;
    }
    toast("請打字說明，或上傳照片／檔案");
    return;
  }
  const pending = list.filter(x => x.needCompany || x.needBank);
  if (pending.length) { toast("還有 " + pending.length + " 張還沒選公司或銀行"); return; }
  if (!state.errands) state.errands = [];
  if (!state.books) state.books = [];
  let nCash = 0, nOut = 0, nIn = 0, nLink = 0;
  list.forEach((g, idx) => {
    const date = ymdOf((g && g.date) || nowStamp());
    const amount = Number(g && g.amount) || 0;
    const title = (g && g.title) || (amount ? "入帳" : "現場紀錄");
    const place = (g && g.place) || "";
    const note = (g && g.note) || "";
    const company = normalizeBookCompany((g && g.company) || "統潔");
    const id = "er" + Date.now() + "-" + idx;
    const pendingBank = !!(g && g.pendingBank);
    const xfer = (g && g.cashType) === "xfer" || !!(g && g.xfer);
    const cashType = xfer ? "xfer" : ((g && g.cashType) === "out" ? "out" : "in");
    const bankLike = cashType !== "out" && (/跑銀行|入帳|對帳|存摺|簿子|轉帳/.test(title) || /聯邦|兆豐|農會/.test(place) || xfer);
    const cash = bankLike && amount ? findPendingCashBook(amount, date) : null;
    if (amount && cash) {
      cash.linkedId = id;
      cash.pendingBank = false;
      cash.editedAt = Date.now();
      state.books.push({
        id: "bk" + Date.now() + "-c" + idx, type: "out", date, amount, company: "現金(保險箱)",
        bank: "", note: "轉存銀行（對應 " + (cash.note || "現金收租") + "）", linkedId: cash.id, editedAt: Date.now()
      });
      state.books.push({
        id: "bk" + Date.now() + "-b" + idx, type: "in", date, amount, company: company === "現金(保險箱)" ? "統潔" : company,
        bank: place, note: "銀行入帳（對應先前現金）", linkedId: cash.id, editedAt: Date.now()
      });
      nLink += 1;
    } else if (amount && xfer) {
      const from = g.fromAccount || "現金(保險箱)";
      const toCo = company === "現金(保險箱)" ? "統潔" : company;
      state.books.push({
        id: "bk" + Date.now() + "-x" + idx, type: "out", date, amount, company: from,
        bank: "", note: "轉帳　" + (note || title), linkedId: id, editedAt: Date.now()
      });
      state.books.push({
        id: "bk" + Date.now() + "-y" + idx, type: "in", date, amount, company: toCo,
        bank: place, note: "轉帳入　" + (note || title), linkedId: id, editedAt: Date.now()
      });
      nLink += 1;
    } else if (amount) {
      state.books.push({
        id: "bk" + Date.now() + "-" + idx, type: cashType,
        date, amount, company, bank: place, note: note || title,
        pendingBank: cashType === "in" && (pendingBank || company === "現金(保險箱)"),
        linkedId: id
      });
      if (cashType === "out") nOut += 1;
      else if (pendingBank) nCash += 1;
      else nIn += 1;
    }
    state.errands.push({
      id, kind: "bank", date, title, place, amount, note, company,
      pendingBank: pendingBank && !cash, linkedId: cash ? cash.id : id,
      skipLedger: true, summary: g.fileName || "", createdAt: nowStamp()
    });
    const p = date.split("-");
    if (p.length === 3) {
      ui.calYear = Number(p[0]);
      ui.calMonth = Number(p[1]);
      ui.calDay = Number(p[2]);
    }
  });
  ui.errandMedia = [];
  ui.errandAbsorb = "";
  ui.errandGuess = null;
  ui.errandGuesses = [];
  ui.errandNote = "";
  ui.errandOpen = true;
  save();
  toast("已登錄 " + (list.length || 1) + " 筆");
  ui.keepScroll = true;
  render();
  try { pushCloud(); } catch {}
}
