document.addEventListener("pointerdown", e => {
  if (e.button && e.button !== 0) return;
  const t = e.target.closest("button, .nav, .tab, .seg, .theme-swatch, .issue-opt, .fold-head, .errand-ball, .pref-knob, .pay-pill.clickable, .ai-send");
  if (!t) return;
  if (t.closest("input, textarea, select")) return;
  if (t.id === "font-scale" || t.type === "range") return;
  buzz(12);
}, { capture: true, passive: true });
function bindPullRefresh() {
  const sc = document.querySelector(".tenant-scroll") || document.querySelector(".admin-scroll");
  if (!sc) return;
  let ptr = sc.querySelector(":scope > .ptr");
  if (!ptr) {
    ptr = document.createElement("div");
    ptr.className = "ptr";
    ptr.innerHTML = "<em></em><span>下拉重新整理</span>";
    sc.insertBefore(ptr, sc.firstChild);
  }
  if (sc.dataset.ptrBound === "1") return;
  sc.dataset.ptrBound = "1";
  let y0 = 0, pulling = false, dy = 0, busy = false;
  const max = 92, need = 62;
  const live = () => sc.querySelector(":scope > .ptr");
  const setH = (h, text) => {
    const box = live();
    if (!box) return;
    box.style.height = Math.max(0, h) + "px";
    box.classList.toggle("on", h >= need);
    const label = box.querySelector("span");
    if (label) label.textContent = text || (h >= need ? "放開後重新整理" : "下拉重新整理");
  };
  sc.addEventListener("touchstart", e => {
    pulling = false;
    dy = 0;
    if (busy || sc.scrollTop > 2) return;
    if (e.target.closest("form, input, textarea, select, canvas, .swipe-wrap, .seg, .tabs, button, label, a")) return;
    y0 = e.touches[0].clientY;
    pulling = true;
    const box = live();
    if (box) box.style.transition = "none";
  }, { passive: true });
  sc.addEventListener("touchmove", e => {
    if (!pulling || busy) return;
    const raw = e.touches[0].clientY - y0;
    if (raw < -6 || sc.scrollTop > 2) {
      pulling = false;
      setH(0);
      return;
    }
    dy = Math.max(0, raw * 0.45);
    if (dy > 14 && sc.scrollTop <= 0) {
      if (e.cancelable) e.preventDefault();
      setH(Math.min(max, dy));
    }
  }, { passive: false });
  sc.addEventListener("touchend", async () => {
    if (!pulling || busy) return;
    pulling = false;
    const box = live();
    if (box) box.style.transition = "height .25s ease";
    if (dy >= need) {
      busy = true;
      if (box) box.classList.add("busy");
      setH(56, "重新整理中…");
      try {
        await pullCloud();
        if (window.__swReg) window.__swReg.update().catch(() => {});
      } catch {}
      lastRenderPage = ui.page;
      lastRenderRole = ui.role;
      ui.keepScroll = false;
      render();
      showTopHint("已重新整理");
      return;
    }
    setH(0);
    dy = 0;
  });
}
function hideSplash() {
  const el = document.getElementById("splash");
  if (!el || el.dataset.done === "1") return;
  el.dataset.done = "1";
  el.classList.add("out");
  el.style.display = "none";
  setTimeout(() => { if (el.parentNode) el.remove(); }, 450);
}
async function boot() {
  const splashAt = setTimeout(hideSplash, 2200);
  try {
    armCompanySave();
    armAiSend();
    armRoomEditSave();
    restoreUi();
    applyTheme(currentThemeId());
    applyFont(currentFontScale());
    seedSeenVersion();
    if (hasUnseenUpdate()) ui.updateReady = true;
    try { connectPaidCloud(); } catch {}
    await Promise.race([refreshGeo(), new Promise(r => setTimeout(r, 2800))]);
    if (ui.role) audit("再次進入", "關閉後重新打開，維持登入");
    render();
    if (locPrefOn()) askPreciseLocation(false);
    try {
      const idb = await loadLedgerIdb();
      mergeLedgerInto(state, idb);
      mergeLedgerInto(state, loadLedgerBackup());
      dropFactoryRentAutos(state);
      persistLedger(state);
    } catch {}
    const got = await pullCloud();
    try { if (restoreMissingSignAppoint(state)) { markCloudDirty(); await pushCloud(); } } catch {}
    try {
      if (await repairStoredESigns(state)) {
        persistESignsMap(state.eSigns);
        await pushCloud();
      }
    } catch {}
    rollRentMonthIfNeeded();
    applyPaidMarks(state);
    persistPaidMarks(state);
    dropFactoryRentAutos(state);
    persistLedger(state);
    try { connectPaidCloud(); } catch {}
    if (got === "local-newer" || cloudDirty) await pushCloud();
    restoreUi();
    beatPresence();
    render();
    refreshSky(true).then(() => {
      if (ui.role === "tenant") applySkyDom();
    }).catch(() => {});
    if (ui.role || isInstalledApp()) { enablePush().then(() => maybeNudgeNotifies()).catch(() => {}); armPushAsk(); }
  } catch (err) {
    try { console.error(err); } catch {}
    try { render(); } catch {}
  }
  clearTimeout(splashAt);
  hideSplash();
  const syncTick = async () => {
    if (syncTick.busy) return;
    syncTick.busy = true;
    try {
      if (rollRentMonthIfNeeded()) {
        ui.keepScroll = true;
        render();
      }
      const before = {
        anns: (state.announcements || []).map(a => a.id),
        repairIds: (state.repairs || []).map(r => r.id),
        repairSnap: Object.fromEntries((state.repairs || []).map(r => [r.id, (r.status || "") + "|" + (r.appointAt || "")])),
        renewIds: (state.renewals || []).map(x => x.id)
      };
      const prevSig = coreSig(state);
      const changed = await pullCloud();
      try { await pullBuild(); } catch {}
      try { await pollRemoteBuild(); } catch {}
      refreshOnlineBadges();
      if (coreSig(state) !== prevSig) {
        notifyCloudChanges(before);
        if (composingNow()) {
          captureComposeDraft();
          return;
        }
        ui.keepScroll = true;
        render();
      }
    } catch {}
    finally { syncTick.busy = false; }
  };
  setInterval(syncTick, 1500);
  setTimeout(syncTick, 200);
  setInterval(beatPresence, 25000);
  setInterval(() => { refreshSky().catch(() => {}); }, 15 * 60 * 1000);
  document.addEventListener("visibilitychange", () => {
    if (document.visibilityState === "visible") {
      beatPresence();
      syncTick();
      if (locPrefOn()) askPreciseLocation(false);
    }
  });
}
